let route=[],toastTimer,lastFocus=null;
function restoreFields(){for(const [id,value] of Object.entries(state.config)){const e=document.getElementById(id);if(e)e.value=value}}
function nav(path){if(location.hash==='#'+path)render();else location.hash=path}
function toast(t){clearTimeout(toastTimer);document.getElementById('toasts').innerHTML=`<div class="toast">${ic('check')}${esc(t)}</div>`;toastTimer=setTimeout(()=>document.getElementById('toasts').innerHTML='',3200)}
function openDrawer(title,body,footer='',wide=false){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="drawerback" onclick="if(event.target===this)closeDrawer()"><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawerheader"><h2>${esc(title)}</h2><button class="iconbtn" aria-label="关闭详情" onclick="closeDrawer()">${ic('close')}</button></div><div class="drawerbody">${body}</div>${footer?`<div class="drawerfooter">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';restoreFields();document.querySelector('.drawerheader button').focus()}
function closeDrawer(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&document.querySelector('.drawer')){const list=[...document.querySelectorAll('.drawer button,.drawer input,.drawer select,.drawer textarea,.drawer a')].filter(el=>!el.disabled&&el.offsetParent!==null);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}});
function head(en,title,sub,actions=''){return `<header class="pagehead"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></header>`}
function tabs(items){return `<nav class="tabs" aria-label="页面分栏">${items.map(([title,path,count])=>`<a href="#${path}" class="${(route.join('/')===path||(route.length===1&&items[0][1]===path))?'active':''}">${title}${count!=null?pill(count,'gray'):''}</a>`).join('')}</nav>`}
function kpis(data){return `<div class="kpis">${data.map(([label,value,unit,foot,ico])=>`<div class="kpi"><div class="kpi-label">${label}${ic(ico||'analytics')}</div><div class="kpi-value">${value}<small>${unit||''}</small></div><div class="kpi-foot">${foot||'截至 2026.11.14'}</div></div>`).join('')}</div>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">暂无匹配记录</td></tr>`}</tbody></table></div>`}
function panel(title,content,action=''){return `<section class="panel"><div class="panelhead"><h2>${title}</h2>${action}</div>${content}</section>`}
function productcell(p){return `<div class="productcell"><div class="thumb">${garment(p)}</div><div><strong>${p.id}</strong><small>${esc(p.name)}</small></div></div>`}
function field(label,id,value='',type='text',hint=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="1"':''}>${hint?`<small>${hint}</small>`:''}</div>`}
function selectfield(label,id,values){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${values.map((v,i)=>`<option value="${i}">${esc(v)}</option>`).join('')}</select></div>`}
function footer(text,count){return `<div class="listfooter"><span>${text}</span><span>共 ${count} 条 · 当前全部展示</span></div>`}
function exportCSV(name,headers,rows){const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前演示数据')}
function exportCurrent(){const m=route[0];if(m==='customers')exportCSV('客户账款',['客户','分类','应收余额'],customers.map(c=>[c.name,c.type,c.due]));else if(m==='orders')exportCSV('客户订单',['单号','客户','订货','已发','欠货'],orders.map(o=>[o.id,customers[o.customer].name,o.qty,o.sent,o.qty-o.sent]));else if(m==='staff')exportCSV('配货提成',['员工','有效件数','应发提成含跨期调整','结算状态'],members.map((m,i)=>[m.name,m.qty,m.pay-(i===0?5:0),state.locked?'已锁定':'待复核']));else if(m==='returns')exportCSV('退货记录',['退货单','客户','数量','原因','状态'],state.returns.map(r=>[r.id,customers[r.customer].name,r.qty,r.reason,r.status]));else exportCSV('款式销售库存',['款号','品名','颜色','价格','库存','近14天销量','状态'],products.map(p=>[p.id,p.name,p.colorName,p.price,p.stock,p.sales,p.off?'已下架':'已上架']))}
function render(){route=location.hash.slice(1).split('/').filter(Boolean);if(!route.length)route=['products'];if(route[0]==='share'){renderShare();return}if(!menus.some(m=>m[0]===route[0]))route=['products'];const current=menus.find(m=>m[0]===route[0]);document.title=current[2]+' · 梧桐朴鲤';document.getElementById('app').innerHTML=`<aside class="sidebar" id="sidebar"><button class="mobileclose" aria-label="关闭菜单" onclick="document.getElementById('sidebar').classList.remove('open')">${ic('close')}</button><a class="brand" href="#products"><span class="brandmark">${ic('leaf')}</span><span><strong>梧桐朴鲤</strong><small>WUTONG PULI</small></span></a><div class="store">${ic('location')}<div><b>杭州展厅</b><small>销售端 · 秋冬 2026</small></div></div><div class="navlabel">销售工作台</div><nav class="nav">${menus.map(m=>`<a href="#${m[0]}" class="${route[0]===m[0]?'active':''}">${ic(m[1])}<span>${m[2]}</span>${m[0]==='orders'?'<em>5</em>':m[0]==='production'?`<em>${state.suggestions.filter(s=>s.status==='待确认').length}</em>`:''}</a>`).join('')}</nav><div class="navfoot">${avatar()}<div><b>林予安</b><small class="tiny" style="display:block;margin-top:4px">负责人 · 演示账号</small></div><button class="textbtn" aria-label="账号权限" onclick="nav('settings/permissions')">${ic('settings')}</button></div></aside><div class="workspace"><div class="topbar"><div class="breadcrumb"><button class="menutoggle iconbtn" aria-label="展开菜单" onclick="document.getElementById('sidebar').classList.add('open')">${ic('list')}</button><span>销售工作台</span><span>/</span><b>${current[2]}</b></div><div class="topactions"><button class="topsearch" onclick="globalSearch()">${ic('search')}搜索款号、客户、订单</button><span class="demo"><i class="dot"></i>高保真交互演示</span><a href="./index.html">PC 开发后台</a><button class="iconbtn" aria-label="查看待办通知" onclick="notifications()">${ic('bell')}</button></div></div><main class="main" id="main">${({products:productsPage,customers:customersPage,orders:ordersPage,sales:salesPage,returns:returnsPage,inventory:inventoryPage,production:productionPage,analytics:analyticsPage,staff:staffPage,scan:scanPage,settings:settingsPage}[route[0]])()}</main></div><div class="floatingnote">设计预览 V8 · 全部为示例数据，操作仅在当前页面会话生效</div>`;restoreFields()}
window.addEventListener('hashchange',()=>{closeDrawer();state.q='';render();window.scrollTo(0,0)});

function productsPage(){let s=route[1]||'catalog';return head('PRODUCT COLLECTION','产品管理','从一件好衣开始，管理每一款的销售生命周期。',btn('导出货品','exportCurrent()','','download')+btn('新增货品','productForm()','primary','plus'))+kpis([['在售款式',products.filter(p=>!p.off).length,'款','<b>2026 AW</b> 秋冬销售系列','product'],['可售库存',num(products.reduce((a,p)=>a+p.stock,0)),'件','总仓与展厅仓汇总','inventory'],['近 14 天净销量',num(products.reduce((a,p)=>a+p.sales,0)),'件','<b>+12.8%</b> 较上一周期','analytics'],['待处理下架建议',products.filter(p=>p.warn&&!p.off&&!p.ignored).length,'款','留住好款，也及时告别','bell']])+tabs([['货品列表','products/catalog',products.length],['下架通知','products/delist',products.filter(p=>p.warn&&!p.off&&!p.ignored).length],['上下架记录','products/history']])+(s==='delist'?delistPage():s==='history'?panel('上下架记录',table(['款号','操作','范围','时间','操作人'],products.filter(p=>p.off).map(p=>[p.id,pill('已下架','gray'),'杭州展厅 / 整款','刚刚','林予安']))):catalog());}
function catalog(){return `<div class="toolbar"><div class="filters"><div class="inputsearch">${ic('search')}<input aria-label="搜索货品" placeholder="搜索款号、品名、颜色" oninput="state.q=this.value;refreshCatalog()" value="${esc(state.q)}"></div><select aria-label="筛选销售状态" onchange="state.category=this.value;refreshCatalog()"><option value="all">全部销售状态</option><option value="on" ${state.category==='on'?'selected':''}>已上架</option><option value="off" ${state.category==='off'?'selected':''}>已下架</option><option value="warn" ${state.category==='warn'?'selected':''}>建议下架</option></select></div><div class="segmented"><button aria-label="卡片视图" class="${state.view==='grid'?'active':''}" onclick="state.view='grid';render()">${ic('grid')}</button><button aria-label="列表视图" class="${state.view==='list'?'active':''}" onclick="state.view='list';render()">${ic('list')}</button></div></div><div class="cataloglayout"><div><div id="catalogResults">${catalogResults()}</div>${footer('已展示全部演示款式',products.length)}</div><aside class="stack"><section class="asidelead"><div class="eyebrow">A MORE MINDFUL COLLECTION</div><h2>让每一款，<br>都恰逢其时。</h2><p>关注销售的变化，把空间留给<br>更值得期待的新款。</p>${btn('查看下架建议',"nav('products/delist')",'','arrow')}</section><section class="panel pad"><h2 style="font-size:13px">本期热销</h2>${products.slice(0,3).map((p,i)=>`<div class="miniitem"><div class="thumb">${garment(p)}</div><div><h3>${esc(p.name)}</h3><p>${p.id} · ${p.sales} 件</p></div></div>`).join('')}</section><div class="note">新品保护期 <b>${state.rules.protect} 天</b><br>缺货或销售样本不足时，先观察，不直接判断滞销。</div></aside></div>`}
function filteredProducts(){return products.filter(p=>(p.id+p.name+p.colorName).toLowerCase().includes(state.q.toLowerCase())&&(state.category==='all'||state.category==='on'&&!p.off||state.category==='off'&&p.off||state.category==='warn'&&p.warn))}
function refreshCatalog(){document.getElementById('catalogResults').innerHTML=catalogResults()}
function catalogResults(){const ps=filteredProducts();if(!ps.length)return '<div class="panel empty">没有找到匹配货品<br><small>试试款号 WT-2608 或清除筛选条件</small></div>';return state.view==='list'?`<div class="panel">${table(['货品','颜色 / 成分','销售价','可售库存','状态',''],ps.map(p=>[productcell(p),p.colorName+`<small>${esc(p.composition)}</small>`,money(p.price),num(p.stock),pill(p.off?'已下架':p.warn?'建议下架':'已上架',p.off?'gray':p.warn?'amber':''),btn('查看',`productDetail('${p.id}')`,'textbtn','arrow')]))}</div>`:`<div class="products">${ps.map(p=>`<button class="productcard" onclick="productDetail('${p.id}')"><div class="productart">${garment(p)}${pill(p.off?'已下架':p.tags,p.off?'gray':p.warn?'amber':'')}<span class="favorite">${ic('heart')}</span></div><div class="productbody"><div class="productcode">${p.id}<span>2026 AW</span></div><h3>${esc(p.name)}</h3><div class="swatches"><i class="swatch" style="background:${p.color}"></i><i class="swatch" style="background:#e1d6bd"></i><i class="swatch" style="background:#7d8073"></i><span class="tiny" style="margin-left:5px">${esc(p.colorName)} 等 3 色</span></div><div class="productbottom"><span class="price">¥${p.price}</span><span class="stocktext">可售 ${p.stock} 件</span></div></div></button>`).join('')}</div>`}
function productDetail(id,tab='info'){const p=products.find(p=>p.id===id);openDrawer(p.name,`<div class="productart">${garment(p)}</div><div class="rowline"><span class="mono">${p.id}</span>${pill(p.off?'已下架':'已上架',p.off?'gray':'')}</div><div class="tabs" style="margin-top:22px">${[['info','基本信息'],['stock','色码库存'],['sales','销售表现']].map(([k,n])=>`<a href="javascript:void(0)" class="${k===tab?'active':''}" onclick="productDetail('${id}','${k}')">${n}</a>`).join('')}</div>${tab==='info'?`<dl class="detailgrid">${[['款号',p.id],['销售价格',money(p.price)],['主色',p.colorName],['尺码','S / M / L / XL'],['成分',p.composition],['上架日期','2026.10.12'],['所属系列','2026 秋冬 / 通勤日常'],['商品来源','PC 后台 · 已定版成衣']].map(([l,v])=>`<div><dt>${l}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="note">柔软亲肤的日常针织，适合叠穿。色卡与实物图片通过标准颜色 ID 关联。</div>`:tab==='stock'?table(['颜色','S','M','L','XL','可售合计'],[[p.colorName,Math.floor(p.stock*.2),Math.floor(p.stock*.3),Math.floor(p.stock*.3),p.stock-Math.floor(p.stock*.2)-2*Math.floor(p.stock*.3),p.stock],['米白','0','6','0','0','6']])+`<p class="tiny" style="margin-top:16px">主要仓库：杭州总仓 A-02 · 点击库存管理可查看批次与流水。</p>`:kpis([['14 天净销量',p.sales,'件','有效销售 − 退货'],['可售库存',p.stock,'件','杭州总仓']])+trendChart()+`<div class="note">${p.warn?'近 14 天销量较低，已进入下架观察。':'销售表现稳定，建议继续关注尺码缺货。'}</div>`}`,btn(p.off?'恢复上架':'申请下架',`listing('${id}')`,p.off?'soft':'danger')+btn('进入销售开单',`closeDrawer();nav('sales/new')`,'primary','sales'));}
function listing(id){const p=products.find(p=>p.id===id);if(p.off){p.off=false;toast('已恢复上架 · 演示');closeDrawer();render();return}openDrawer('确认下架款式',`<div class="panel pad">${productcell(p)}<dl class="detailgrid"><div><dt>剩余库存</dt><dd>${p.stock} 件</dd></div><div><dt>近 14 天净销量</dt><dd>${p.sales} 件</dd></div></dl></div><div class="note amber" style="margin:20px 0">下架后停止新增销售，已有订单履约、退货和历史查询继续保留。</div>${field('下架原因','offReason','低动销，调整销售款式结构')}<div class="field"><label>生效范围</label><select><option>杭州展厅 · 整款全部 SKU</option></select></div>`,btn('返回','closeDrawer()')+btn('确认下架',`confirmOff('${id}')`,'primary'));}
function confirmOff(id){if(!document.getElementById('offReason').value.trim()){toast('请填写下架原因');return}products.find(p=>p.id===id).off=true;closeDrawer();render();toast('款式已下架，历史单据保留')}
function productForm(){openDrawer('新增销售货品',`<p class="subtle" style="margin-bottom:22px">完善销售资料，建立新的款号列表记录。</p><div class="formgrid">${field('款号','newCode','WT-2628')}${field('品名','newName','轻柔羊毛圆领衫')}${field('销售价','newPrice',268,'number')}${field('颜色','newColor','浅燕麦')}${field('成分','newComposition','100% 羊毛')}${field('初始库存','newStock',0,'number','库存通过正式入库建立，此处为演示')}</div>`,btn('取消','closeDrawer()')+btn('保存货品','saveProduct()','primary'));}
function saveProduct(){const id=document.getElementById('newCode').value.trim(),name=document.getElementById('newName').value.trim(),price=+document.getElementById('newPrice').value,stock=+document.getElementById('newStock').value;if(!/^[A-Za-z0-9_-]{2,32}$/.test(id)||!name||!Number.isFinite(price)||price<=0||stock<0||!Number.isInteger(stock)){toast('请填写款号、品名及有效价格与整数库存');return}if(products.some(p=>p.id===id)){toast('款号已存在，请更换款号');return}products.push({id,name,price,stock,sales:0,composition:document.getElementById('newComposition').value,colorName:document.getElementById('newColor').value,color:'#c7bda9',dark:'#afa58e',tags:'新品保护'});closeDrawer();nav('products/catalog');render();toast('新货品已加入列表 · 演示')}
function delistPage(){const ps=products.filter(p=>p.warn&&!p.off&&!p.ignored);return `<div class="toolbar"><p class="subtle" style="font-size:12px">按近 ${state.rules.days} 天销量评估 · 新品保护 ${state.rules.protect} 天</p>${btn('自定义下架规则','delistRules()','','settings')}</div>`+panel('待处理下架建议',table(['货品','触发原因','可售库存','建议状态','操作'],ps.map(p=>[productcell(p),`近 ${state.rules.days} 天净销量 ${p.sales} 件<small>已上架 42 天 · 有货 14 天</small>`,p.stock+' 件',pill('等待你的决定','amber'),`<div class="actions">${btn('查看',`productDetail('${p.id}')`,'textbtn')}${btn('下架',`listing('${p.id}')`,'soft')}${btn('延后观察',`deferProduct('${p.id}')`,'textbtn')}</div>`])))+`<div class="note" style="margin-top:20px">建议不会自动改变上架状态。缺货、新品或样本不足的款式会进入保护观察。</div>`}
function deferProduct(id){products.find(p=>p.id===id).ignored=true;render();toast('已延后 7 天观察 · 演示')}
function delistRules(){openDrawer('下架通知规则',`<div class="note" style="margin-bottom:22px">所有条件同时满足时生成下架建议，仍需你确认后执行。</div><div class="formgrid">${field('观察窗口 / 天','ruleDays',state.rules.days,'number')}${field('净销量不超过 / 件','ruleSales',state.rules.sales,'number')}${field('库存不少于 / 件','ruleStock',state.rules.stock,'number')}${field('新品保护期 / 天','ruleProtect',state.rules.protect,'number')}${field('提醒冷却期 / 天','ruleCooldown',state.rules.cooldown,'number')}</div><label class="checkrow"><input type="checkbox" checked>排除缺货、重点保留款和样本不足款式</label><div id="rulePreview" class="note">当前参数预计命中 ${products.filter(p=>p.sales<=state.rules.sales&&p.stock>=state.rules.stock).length} 款演示货品。</div>`,btn('试算','previewRules()')+btn('保存规则','saveRules()','primary'));}
function ruleValues(){return {days:+document.getElementById('ruleDays').value,sales:+document.getElementById('ruleSales').value,stock:+document.getElementById('ruleStock').value,protect:+document.getElementById('ruleProtect').value,cooldown:+document.getElementById('ruleCooldown').value}}
function validRule(r){return Object.values(r).every(v=>Number.isInteger(v)&&v>=0)&&r.days>0}
function previewRules(){const r=ruleValues();if(!validRule(r)){toast('请输入有效整数，观察天数须大于零');return}document.getElementById('rulePreview').textContent=`试算命中 ${products.filter(p=>p.sales<=r.sales&&p.stock>=r.stock&&!p.off).length} 款：${products.filter(p=>p.sales<=r.sales&&p.stock>=r.stock&&!p.off).map(p=>p.id).join('、')||'无'}。采用演示快照，正式系统会校验完整保护条件。`}
function saveRules(){const r=ruleValues();if(!validRule(r)){toast('请检查规则数值');return}state.rules=r;products.forEach(p=>p.warn=p.sales<=r.sales&&p.stock>=r.stock);closeDrawer();render();toast('下架规则已保存，建议列表已更新')}

function customersPage(){const sub=route[1]||'list';return head('CUSTOMER RELATIONSHIPS','客户信息','了解每一位客户，让每一次合作都更有秩序。',btn('导出对账','exportCurrent()','','download')+btn('新增客户','customerForm()','primary','plus'))+kpis([['合作客户',customers.length,'位','按当前门店授权展示','customers'],['累计成交',money(customers.reduce((a,c)=>a+c.total,0)),'','长期合作的每一笔积累','money'],['待收账款',money(customers.reduce((a,c)=>a+c.due,0)),'','已核销收款不重复计入','sales'],['逾期客户',customers.filter(c=>c.days>0).length,'位','本周需要重点跟进','clock']])+tabs([['客户档案','customers/list'],['客户账款','customers/accounts'],['催款设置','customers/reminders']])+(sub==='reminders'?reminderSettings():panel(sub==='accounts'?'客户应收与账龄':'客户档案',table(['客户','分类 / 标签','累计成交','待收账款','最近合作',''],customers.map((c,i)=>[`<div class="productcell">${avatar(i)}<div><strong>${esc(c.name)}</strong><small>${esc(c.person)} · ${esc(c.city)}</small></div>`,pill(c.type)+`<small>${esc(c.tags)}</small>`,money(c.total),`${money(c.due)}${c.days?`<small style="color:var(--red)">逾期 ${c.days} 天</small>`:'<small>账期内</small>'}`,'2026.11.14',btn(sub==='accounts'?'查看账款':'客户详情',`customerDetail(${i})`,'textbtn','arrow')]))));}
function customerDetail(i){const c=customers[i];openDrawer(c.name,`<div class="memberhead">${avatar(i)}<div><h2>${esc(c.name)}</h2><p class="tiny">${c.id} · ${esc(c.person)} · ${esc(c.city)}</p></div></div><div class="actions">${pill(c.type)}${pill(c.tags,'blue')}</div><dl class="detailgrid"><div><dt>结算方式</dt><dd>月结 30 天</dd></div><div><dt>专属价目表</dt><dd>长期合作价</dd></div><div><dt>待收账款</dt><dd style="font-size:24px;color:var(--green)">${money(c.due)}</dd></div><div><dt>合作订单</dt><dd>${c.orders} 单</dd></div></dl>${panel('最近账款明细',table(['业务','应收 / 核销','日期'],[['销售出库',money(c.due+6000),'11.12'],['收款核销','−¥6,000.00','11.13'],['剩余应收',money(c.due),'当前']]))}<div class="note ${c.days?'amber':''}" style="margin-top:20px">${c.days?'当前逾期 '+c.days+' 天，建议跟进回款安排。':'账期内，暂未产生逾期。'} 外发催款需要独立接入，当前仅演示内部提醒。</div>`,btn('记录收款',`receiptForm(${i})`,'soft','money')+btn('生成内部催款待办',`toast('已创建该客户的内部催款待办');closeDrawer()`,'primary','bell'));}
function receiptForm(i){openDrawer('记录收款与核销',`<p style="margin-bottom:20px">${customers[i].name} · 待收 ${money(customers[i].due)}</p>${field('本次到账金额','receiptAmount',Math.min(6000,customers[i].due),'number')}${selectfield('收款方式','receiptMethod',['银行转账','微信收款','现金'])}<div class="note">本次演示直接分配至该客户最早到期的应收单，未收款不会自动视为已到账。</div>`,btn('确认核销',`confirmReceipt(${i})`,'primary'));}
function confirmReceipt(i){let v=+document.getElementById('receiptAmount').value;if(v<=0||v>customers[i].due){toast('金额须大于 0 且不超过待收余额');return}customers[i].due-=v;closeDrawer();render();toast('收款已核销，客户余额已更新 · 演示')}
function customerForm(){openDrawer('新增客户档案',`<div class="formgrid">${field('客户名称','cName')}${field('联系人','cPerson')}${field('所在城市','cCity','杭州')}${selectfield('客户分类','cType',['成长客户','长期客户','核心客户'])}</div>`,btn('保存客户','saveCustomer()','primary'));}
function saveCustomer(){let n=document.getElementById('cName').value.trim(),p=document.getElementById('cPerson').value.trim();if(!n||!p){toast('请填写客户名称和联系人');return}if(customers.some(c=>c.name===n)){toast('同名客户已存在');return}customers.push({id:'C00'+(customers.length+1),name:n,person:p,city:document.getElementById('cCity').value,type:['成长客户','长期客户','核心客户'][+document.getElementById('cType').value],orders:0,total:0,due:0,days:0,tags:'新客户'});closeDrawer();render();toast('客户档案已创建')}
function reminderSettings(){return `<div class="two"><section class="panel pad"><div class="rowline"><div><h3>自动生成催款待办</h3><p class="tiny">仅向负责人发送站内提醒</p></div><button aria-label="切换催款提醒" class="toggle ${state.reminder?'on':''}" onclick="state.reminder=!state.reminder;render()"></button></div><div class="formgrid" style="margin-top:23px">${field('到期前提醒 / 天','remindBefore',3,'number')}${field('逾期后提醒 / 天','remindAfter',1,'number')}${field('重复提醒间隔 / 天','remindGap',3,'number')}${field('最低欠款金额 / 元','remindMin',100,'number')}</div>${btn('保存催款设置',"saveConfig('催款设置已保存')",'primary')}</section><section class="panel pad"><h2>客户收到什么</h2><p style="font-size:12px;margin:20px 0;color:var(--muted)">尊敬的客户，您有一笔应结账款待处理，请核对本期对账单。如已付款，请联系您的专属销售顾问。</p><div class="note">站内待办已可体验。短信、微信等对客发送渠道未连接，不会实际发送消息。</div></section></div>`}

function ordersPage(){if(route[1]&&orders.some(o=>o.id===route[1]))return orderDetailPage(orders.find(o=>o.id===route[1]));return head('CUSTOMER ORDERS','客户订单','接好每一张订单，让交期、欠货与包装要求都有迹可循。',btn('导出订单','exportCurrent()','','download')+btn('新增订货','orderForm()','primary','plus'))+kpis([['有效订货',num(orders.reduce((a,o)=>a+o.qty,0)),'件','已确认的交付承诺','orders'],['累计发货',num(orders.reduce((a,o)=>a+o.sent,0)),'件','按实际出库记录汇总','box'],['待发欠货',num(orders.reduce((a,o)=>a+o.qty-o.sent,0)),'件','与生产进度独立计算','clock'],['本周需交付','4','单','最早交期 11 月 17 日','calendar']])+panel('订单列表',table(['订单 / 客户','款式','订货 / 已发','约定交期','履约状态','独立详情'],orders.map(o=>[`${o.id}<small>${esc(customers[o.customer].name)}</small>`,productcell(products[o.p]),`${o.qty} / ${o.sent}<small>欠货 ${o.qty-o.sent} 件</small>`,`2026-${o.date}`,pill(o.status,o.sent===o.qty?'':o.sent?'amber':'gray'),`<div class="actions"><a href="#orders/${o.id}">订单</a><a href="#orders/${o.id}/shortage">欠货</a><a href="#orders/${o.id}/packing">包装要求</a></div>`])));}
function orderDetailPage(o){const p=products[o.p],sub=route[2]||'overview';return head('ORDER DETAIL',o.id,customers[o.customer].name+' · '+p.name,btn('返回列表',"nav('orders')",'','back')+btn('客户进度预览',`nav('share/${o.id}')`,'soft','share'))+tabs([['订单信息',`orders/${o.id}`],['欠货详情',`orders/${o.id}/shortage`,o.qty-o.sent],['定标包装要求',`orders/${o.id}/packing`]])+(sub==='packing'?`<div class="two"><section class="panel pad"><div class="actions" style="justify-content:space-between"><h2>客户包装规范</h2>${pill('已确认 · V3')}</div><dl class="detailgrid"><div><dt>吊牌</dt><dd>青禾品牌吊牌 / 正面款号贴</dd></div><div><dt>洗标</dt><dd>按确认成分及尺码缝制</dd></div><div><dt>单件包装</dt><dd>独立磨砂袋 · 尺码贴在右上角</dd></div><div><dt>装箱要求</dt><dd>同色同码整包 / 每包 10 件</dd></div></dl><div class="note">确认版本绑定当前订单批次。新模板不会覆盖已发批次，变更需要重新确认。</div></section><section class="panel pad"><h2>版本确认记录</h2><div class="timeline"><div class="event active"><b>客户确认 V3</b><p>11.13 14:20 · 陈女士</p></div><div class="event"><b>更新尺码贴位置</b><p>11.13 11:40 · 林予安</p></div><div class="event"><b>包装要求初稿 V1</b><p>11.12 09:30</p></div></div></section></div>`:`${kpis([['订货数量',o.qty,'件','已确认'],['累计已发',o.sent,'件','实发累计'],['待发欠货',o.qty-o.sent,'件','普通退货不自动恢复欠货'],['预计交期',o.date,'','2026 年']])}<div class="two">${panel(sub==='shortage'?'按色码查询欠货':'订单商品明细',table(['款色码','有效订货','累计已发','欠货'],['S','M','L','XL'].map((size,i)=>{let q=Math.round(o.qty*[.2,.3,.3,.2][i]),sent=Math.round(o.sent*[.2,.3,.3,.2][i]);return [`${p.id} / ${size}<small>${esc(p.colorName)}</small>`,q,sent,q-sent]})))}<section class="panel pad"><h2>交付记录</h2><div class="timeline"><div class="event active"><b>${o.sent===o.qty?'已发齐':'等待下一批交付'}</b><p>${o.qty-o.sent} 件待发 · 交期 2026-${o.date}</p></div><div class="event"><b>已出库 ${o.sent} 件</b><p>杭州总仓 · 累计实际发货</p></div><div class="event"><b>订单数量已确认</b><p>关联包装要求 V3</p></div></div><div style="margin-top:25px">${btn('从订单开单',`nav('sales/new')`,'primary','sales')}</div></section></div>`);}
function orderForm(){openDrawer('新增客户订货',`<div class="formgrid">${selectfield('客户','orderCustomer',customers.map(c=>c.name))}${selectfield('货品','orderProduct',products.map(p=>p.id+' '+p.name))}${field('订货数量','orderQty',100,'number')}${field('约定交期','orderDate','2026-11-25','date')}</div><div class="note">确认订单产生交付需求，不直接扣减实物库存或计入销售额。</div>`,btn('确认订货','saveOrder()','primary'));}
function saveOrder(){const q=+document.getElementById('orderQty').value,date=document.getElementById('orderDate').value;if(!Number.isInteger(q)||q<=0||!date){toast('请输入正整数数量与交期');return}orders.unshift({id:'SO261114'+String(orders.length+1).padStart(2,'0'),customer:+document.getElementById('orderCustomer').value,p:+document.getElementById('orderProduct').value,qty:q,sent:0,date:date.slice(5),status:'待配货'});closeDrawer();render();toast('客户订单已确认 · 演示')}

function salesPage(){const sub=route[1]||'new';return head('SALES WORKSPACE','销售开单','款色码快速录入，配货、发货与账款准确衔接。',btn('查看客户订单',"nav('orders')",'','orders'))+tabs([['新建销售单','sales/new'],['销售单记录','sales/records',state.sales.length]])+(sub==='records'?panel('销售单记录',table(['销售单号','客户','款号','数量','金额','状态',''],state.sales.map(s=>[s.id,customers[s.customer].name,products[0].id,s.qty,money(s.total),pill('待配货','amber'),btn('详情',`saleDetail('${s.id}')`,'textbtn')]))):`<div class="two"><div class="stack"><section class="panel pad"><h2 style="margin-bottom:22px">客户与交付信息</h2><div class="formgrid">${selectfield('客户','saleCustomer',customers.map(c=>c.name))}${selectfield('出库仓库','saleWarehouse',['杭州总仓','杭州展厅仓'])}${field('单据日期','saleDate','2026-11-14','date')}${selectfield('结算方式','salePayment',['客户月结价','现款结算'])}</div></section><section class="panel"><div class="panelhead"><h2>商品明细</h2>${pill('色码矩阵录入','gray')}</div><div class="pad">${productcell(products[0])}<div style="height:20px"></div><div class="tablewrap matrix"><table><thead><tr><th>颜色 / 尺码</th>${['S','M','L','XL'].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody><tr><td>${products[0].colorName}</td>${state.cart.map((v,i)=>`<td><input aria-label="${['S','M','L','XL'][i]} 尺码数量" type="number" min="0" step="1" value="${v}" oninput="updateCart(${i},this.value)"><small>可售 ${[57,86,86,57][i]}</small></td>`).join('')}</tr></tbody></table></div><div class="note" style="margin-top:22px">扫码配货时核对实际颜色与尺码；退货请从左侧独立入口办理。</div></div></section></div><section class="panel pad" style="align-self:start"><div class="actions" style="justify-content:space-between"><h2>本单汇总</h2>${pill('草稿','gray')}</div><div id="saleSummary">${saleSummary()}</div></section></div>`);}
function saleSummary(){let q=state.cart.reduce((a,b)=>a+b,0);return `<div class="rowline"><span>商品数量</span><b>${q} 件</b></div><div class="rowline"><span>客户成交单价</span><b>${money(products[0].price)}</b></div><div class="rowline"><span>包装要求</span><span class="subtle">客户标准包装 V3</span></div><div class="rowline"><span>销售人员</span><span>林予安</span></div><div class="field" style="margin-top:22px"><label>订单备注</label><textarea id="saleNote" placeholder="填写本次发货要求">同色同码装包，发货前复核。</textarea></div><div class="summarytotal"><p class="tiny">本次销售金额</p><div class="price" style="margin-top:9px">${money(q*products[0].price)}</div>${btn('提交并生成配货任务','submitSale()','primary','check')}<p class="tiny" style="text-align:center;margin-top:12px">提交后待配货，出库过账才扣减库存</p></div>`}
function updateCart(i,v){const note=document.getElementById('saleNote')?.value;state.cart[i]=Math.max(0,Math.floor(Number(v)||0));document.getElementById('saleSummary').innerHTML=saleSummary();if(note!==undefined)document.getElementById('saleNote').value=note}
function submitSale(){let q=state.cart.reduce((a,b)=>a+b,0);if(!q){toast('请至少录入一件商品');return}if(state.cart.some((v,i)=>v>[57,86,86,57][i])){toast('有尺码数量超过可售库存，请调整');return}if(products[0].off){toast('该款已下架，请恢复上架后开单');return}state.sales.unshift({id:'XS261114'+String(state.sales.length+1).padStart(2,'0'),customer:+document.getElementById('saleCustomer').value,qty:q,total:q*products[0].price});nav('sales/records');toast('销售单已生成，等待配货 · 演示')}
function saleDetail(id){const s=state.sales.find(x=>x.id===id);openDrawer(id,`${productcell(products[0])}<dl class="detailgrid"><div><dt>客户</dt><dd>${esc(customers[s.customer].name)}</dd></div><div><dt>状态</dt><dd>待配货</dd></div><div><dt>数量</dt><dd>${s.qty} 件</dd></div><div><dt>金额</dt><dd>${money(s.total)}</dd></div></dl><div class="note">当前为配货待办，不扣减实物库存。正式 ERP 在复核出库后产生库存流水与应收。</div>`,btn('关闭','closeDrawer()','primary'));}

function returnsPage(){return head('RETURNS MANAGEMENT','退货管理','独立收货、逐件质检，把每天的退货情况看清楚。',btn('导出退货','exportCurrent()','','download')+btn('新建退货单','returnForm()','primary','plus'))+kpis([['今日退货单',state.returns.length,'单','按收货日期汇总','returns'],['今日实收',state.returns.reduce((a,r)=>a+r.qty,0),'件','实物与财务分别跟踪','box'],['待质检',state.returns.filter(r=>r.status==='待质检').reduce((a,r)=>a+r.qty,0),'件','未检商品不可销售','clock'],['预估退货金额',money(state.returns.reduce((a,r)=>a+r.qty*products[r.p].price,0)),'','待财务确认金额','money']])+panel('今日退货记录',table(['退货单 / 客户','退回商品','实收数量','退货原因','处理状态',''],state.returns.map((r,i)=>[`${r.id}<small>${esc(customers[r.customer].name)}</small>`,productcell(products[r.p]),r.qty+' 件',esc(r.reason),pill(r.status,r.status==='待质检'?'amber':''),btn('查看退货',`returnDetail(${i})`,'textbtn','arrow')])));}
function returnForm(){openDrawer('新建退货单',`<div class="note" style="margin-bottom:22px">关联原销售明细，普通退货不自动恢复订单欠货。</div><div class="formgrid">${selectfield('客户','returnCustomer',customers.map(c=>c.name))}${selectfield('原销售货品','returnProduct',products.slice(0,3).map(p=>p.id+' / 原发 10 件'))}${field('实收退货数量','returnQty',1,'number','演示原发 10 件，历史已退 3 件，本次最多退 7 件')}${selectfield('退货原因','returnReason',['尺码调整','质量问题','颜色不符','客户取消'])}</div><div class="field"><label>收货备注</label><textarea>实收后进入待质检区，质检通过再转可售。</textarea></div>`,btn('取消','closeDrawer()')+btn('登记退货收货','saveReturn()','primary'));}
function saveReturn(){const qty=+document.getElementById('returnQty').value;const customer=+document.getElementById('returnCustomer').value,product=+document.getElementById('returnProduct').value;const max=7-state.returns.filter(r=>r.newReturn&&r.customer===customer&&r.p===product).reduce((a,r)=>a+r.qty,0);if(!Number.isInteger(qty)||qty<1||qty>max){toast('该原单剩余可退数量为 '+max+' 件');return}state.returns.unshift({id:'RT261114'+String(state.returns.length+1).padStart(2,'0'),customer:+document.getElementById('returnCustomer').value,p:+document.getElementById('returnProduct').value,qty,newReturn:true,reason:['尺码调整','质量问题','颜色不符','客户取消'][+document.getElementById('returnReason').value],status:'待质检'});closeDrawer();render();toast('退货收货已登记，等待质检')}
function returnDetail(i){const r=state.returns[i];openDrawer(r.id,`${productcell(products[r.p])}<dl class="detailgrid"><div><dt>退货客户</dt><dd>${esc(customers[r.customer].name)}</dd></div><div><dt>实收数量</dt><dd>${r.qty} 件</dd></div><div><dt>退货原因</dt><dd>${esc(r.reason)}</dd></div><div><dt>实物状态</dt><dd>${r.status}</dd></div></dl><div class="timeline"><div class="event active"><b>${r.status}</b><p>退货独立处理 · 不影响原订单欠货</p></div><div class="event"><b>仓库已收货</b><p>杭州总仓 · 待检区</p></div><div class="event"><b>财务待确认</b><p>预估抵扣 ${money(r.qty*products[r.p].price)}，尚未调整账款</p></div></div>`,r.status==='待质检'?btn('质检通过并入库',`approveReturn(${i})`,'primary','check'):btn('关闭','closeDrawer()','primary'));}
function approveReturn(i){const r=state.returns[i];if(r.status!=='待质检')return;r.status='已入库';products[r.p].stock+=r.qty;closeDrawer();render();toast('质检通过，已增加可售库存 · 演示')}

function inventoryPage(){const sub=route[1]||'stock';return head('INVENTORY OPERATIONS','库存管理','每一次盘点和流转都有记录，每一种颜色都准确对应。',btn('导出库存','exportCurrent()','','download')+btn('颜色纠错','correctionForm()','primary','edit'))+kpis([['可售库存',num(products.reduce((a,p)=>a+p.stock,0)),'件','按款色码查询','inventory'],['盘点批次',state.counts.length,'批','可查询历史差异与复盘','list'],['调拨在途','2','件','20 件发出 / 18 件实收','box'],['外加工中','20','件','基础圆领 · 胸前绣花','production']])+tabs([['库存查询','inventory/stock'],['盘点批次','inventory/counts'],['库存调拨','inventory/transfers'],['外加工流转','inventory/processing'],['颜色纠错','inventory/corrections']])+(sub==='stock'?panel('款色码库存',table(['货品','标准颜色','可售库存','仓库 / 库位','最近变动',''],products.map(p=>[productcell(p),p.colorName,p.stock+' 件','杭州总仓 / A-02','11.14 10:26',btn('库存流水',`stockDetail('${p.id}')`,'textbtn','arrow')]))):sub==='corrections'?panel('颜色纠错记录',table(['纠错单','错误颜色 → 实际颜色','数量','状态',''],state.corrections.map((c,i)=>[c.id,'米白 M → 奶白 M',c.qty,pill(c.status,c.status==='待审核'?'amber':''),btn('审核详情',`correctionDetail(${i})`,'textbtn')])) ,btn('发起纠错','correctionForm()','soft','plus')):panel({counts:'盘点批次记录',transfers:'调拨记录',processing:'加工流转记录'}[sub]||'库存记录',table(['批次 / 单号','范围与内容','数量','状态',''],(state[sub]||state.counts).map((r,i)=>[r.id,r.scope,r.qty+' 件',pill(r.status,r.status==='已完成'?'':'amber'),btn('查看批次',`inventoryRecord('${sub}',${i})`,'textbtn','arrow')])),btn({counts:'创建盘点批次',transfers:'新增调拨',processing:'创建加工出库'}[sub]||'新增',`inventoryForm('${sub}')`,'soft','plus')));}
function stockDetail(id){let p=products.find(p=>p.id===id);openDrawer('库存流水 · '+id,`${productcell(p)}<dl class="detailgrid"><div><dt>当前可售</dt><dd>${p.stock} 件</dd></div><div><dt>标准颜色</dt><dd>${esc(p.colorName)}</dd></div></dl>${table(['时间','业务','数量'],[['11.14 10:26','成品入库','+60'],['11.13 16:20','销售出库','−40'],['11.12 09:40','调拨入库','+20']])}<div class="note" style="margin-top:20px">以上为节选流水。正式系统支持从单据追溯每一笔库存变动。</div>`,btn('关闭','closeDrawer()','primary'));}
function inventoryForm(type){const labels={counts:['创建盘点批次','盘点范围','杭州总仓 / A 区'],transfers:['新增库存调拨','调拨路线','杭州总仓 → 展厅仓'],processing:['创建加工出库','加工内容','基础圆领 → 胸前绣花']},l=labels[type]||labels.counts;openDrawer(l[0],`${field(l[1],'invScope',l[2])}${field('涉及数量','invQty',20,'number')}<div class="note">${type==='counts'?'建立批次快照，差异经复盘与审核后过账。':'记录本次流转批次，部分收货与差异保持可追溯。'}</div>`,btn('创建记录',`saveInventory('${type}')`,'primary'));}
function saveInventory(type){let q=+document.getElementById('invQty').value,s=document.getElementById('invScope').value.trim();if(!q||!Number.isInteger(q)||q<0||!s){toast('请填写范围与正整数数量');return}state[type].unshift({id:({counts:'CK',transfers:'DB',processing:'JG'}[type])+'261114'+String(state[type].length+1).padStart(2,'0'),scope:s,qty:q,status:type==='counts'?'待盘点':type==='transfers'?'待发出':'待加工'});closeDrawer();render();toast('记录已创建，批次可查询')}
function inventoryRecord(type,i){const r=state[type][i];openDrawer(r.id,`<h3>${esc(r.scope)}</h3><dl class="detailgrid"><div><dt>记录数量</dt><dd>${r.qty} 件</dd></div><div><dt>当前状态</dt><dd>${r.status}</dd></div><div><dt>操作人员</dt><dd>林予安 / 杭州总仓</dd></div><div><dt>创建时间</dt><dd>2026.11.14 09:20</dd></div></dl>${type==='counts'?`<div class="formgrid">${field('账面快照','countBook',r.qty,'number')}${field('实盘数量','countReal',r.qty-2,'number')}</div><div class="note amber">盘点差异提交后进入待复盘，不直接覆盖库存余额。</div>`:`<div class="timeline"><div class="event active"><b>${r.status}</b><p>${type==='transfers'?'已发 20 件，实收 18 件，差异 2 件保持在途。':'基础款已移出可售仓，加工结束后按成品 SKU 收回。'}</p></div><div class="event"><b>批次已创建</b><p>来源单据及处理人员已留档</p></div></div>`}`,type==='counts'?btn('提交实盘记录',`submitCount(${i})`,'primary'):btn('关闭','closeDrawer()','primary'));}
function submitCount(i){const q=+document.getElementById('countReal').value;if(q<0||!Number.isInteger(q)){toast('请输入有效实盘数量');return}state.counts[i].real=q;state.counts[i].status='待复盘';closeDrawer();render();toast('实盘已提交，差异等待复盘审核')}
function correctionForm(){openDrawer('发起颜色纠错',`<div class="note amber" style="margin-bottom:22px">以纠错单成对扣减、增加库存，不改颜色名称，不覆盖原始入库单。</div><div class="formgrid">${field('原错误入库单','errSource','RK26111208')}${field('涉及款号','errStyle','WT-2608')}${field('系统错误颜色','errFrom','米白 / M')}${field('实物正确颜色','errTo','奶白 / M')}${field('纠正数量','errQty',6,'number','原入库 10 件，已有 4 件发货，剩余可调整 6 件')}${field('仓库 / 库位','errWarehouse','杭州总仓 / A-02')}</div><div class="field"><label for="errReason">错误原因与核实依据</label><textarea id="errReason">收货时选择了相近色名，已核对剩余实物及原入库记录。</textarea></div><div class="note">过账预览：米白 M −6 件，奶白 M +6 件；总实物数量保持不变。已发 4 件须单独核实。</div>`,btn('取消','closeDrawer()')+btn('提交审核','saveCorrection()','primary'));}
function saveCorrection(){const q=+document.getElementById('errQty').value,r=document.getElementById('errReason').value.trim();const remaining=6-state.corrections.reduce((a,c)=>a+c.qty,0);if(!Number.isInteger(q)||q<1||q>remaining){toast('剩余可调整数量 '+remaining+' 件，已发或已提交数量不可重复纠正');return}if(!r){toast('请填写核实依据');return}state.corrections.unshift({id:'JC261114'+String(state.corrections.length+1).padStart(2,'0'),qty:q,reason:r,status:'待审核'});closeDrawer();nav('inventory/corrections');render();toast('纠错单已提交，尚未改变库存')}
function correctionDetail(i){const c=state.corrections[i];openDrawer('纠错审核 · '+c.id,`<div class="note">原入库 RK26111208 · WT-2608 · 杭州总仓 A-02</div><div class="detailgrid"><div><p class="tiny">错误库存</p><h2 style="margin-top:10px">米白 / M</h2><p style="color:var(--red);font-size:27px;margin-top:15px">−${c.qty}</p></div><div><p class="tiny">实际库存</p><h2 style="margin-top:10px">奶白 / M</h2><p style="color:var(--green);font-size:27px;margin-top:15px">+${c.qty}</p></div></div><p>${esc(c.reason)}</p><div class="note amber" style="margin-top:20px">演示成对库存分录与审核状态，真实库存过账需后端事务及独立审核人校验。</div>`,c.status==='待审核'?btn('模拟审核通过',`state.corrections[${i}].status='已通过';closeDrawer();render();toast('审核通过，成对调整已记录 · 演示')`,'primary'):btn('关闭','closeDrawer()','primary'));}

function productionPage(){const sub=route[1]||'list';return head('PRODUCTION COLLABORATION','生产协同','把销售需求与生产连接起来，让客户看见交付进度。',btn('新建协同报单','collabForm()','primary','plus'))+kpis([['关联生产单','5','单','读取 PC 生产后台','production'],['本周预计入库','360','件','计划与实发分开展示','box'],['待确认智能建议',state.suggestions.filter(s=>s.status==='待确认').length,'条','确认后才生成正式报单','spark'],['交期需关注','1','单','已更新客户可见说明','clock']])+tabs([['生产单列表','production/list'],['协同报单','production/reports'],['订单进度','production/progress'],['智能报单','production/smart',state.suggestions.filter(s=>s.status==='待确认').length]])+(sub==='smart'?smartPage():sub==='progress'?panel('客户订单进度查询',table(['客户订单','客户','当前节点','完成进度',''],orders.map((o,i)=>[o.id,customers[o.customer].name,['后整质检','套口','已发齐','缝合','排期确认'][i],`<div style="width:130px">${[80,45,100,35,10][i]}%<div class="progress"><i style="width:${[80,45,100,35,10][i]}%"></i></div></div>`,btn('进度与分享',`progressDetail('${o.id}')`,'textbtn','share')]))):sub==='reports'?panel('协同报单记录',table(['报单编号','来源','款号','数量','状态'],state.suggestions.filter(s=>s.status==='已确认').map((s,i)=>['BD2611140'+(i+1),'智能建议 / 人工确认',products[s.p].id,s.qty,pill('已确认待同步','blue')]).concat(state.manualReports||[]))):panel('ERP 生产单列表',table(['生产单号','货品','计划数量','当前工序','完成情况',''],orders.map((o,i)=>['SC2611100'+(i+1),productcell(products[o.p]),o.qty+' 件',['后整质检','套口','成品入库','缝合','排期中'][i],`${[80,45,100,35,10][i]}%<div class="progress"><i style="width:${[80,45,100,35,10][i]}%"></i></div>`,btn('查看进度',`progressDetail('${o.id}')`,'textbtn','arrow')]))));}
function orderTimeline(o){const index=orders.indexOf(o),stage=o.sent===o.qty?6:[4,2,6,1,0][index]??0;return ['订单需求已确认','织片与缝合','套口','洗水','后整与质检','成品入库','已发齐'].slice(0,stage+1).reverse().map((label,i)=>`<div class="event ${i===0?'active':''}"><b>${label}${i===0&&stage!==6?' · 进行中':' · 已完成'}</b><p>${i===0&&stage!==6?'预计交期 2026-'+o.date:'进度记录已同步'}</p></div>`).join('')}
function progressDetail(id){const o=orders.find(o=>o.id===id);openDrawer('订单进度 · '+id,`${productcell(products[o.p])}<div class="rowline"><span>客户</span><b>${esc(customers[o.customer].name)}</b></div><div class="timeline">${orderTimeline(o)}</div><div class="note" style="margin-top:23px">对客页面仅展示订单、款式、交期和进度，隐藏成本、工厂联系人与内部备注。</div>`,btn('预览客户页面',`closeDrawer();nav('share/${id}')`,'soft','share')+btn('复制演示分享链接',`copyShare('${id}')`,'primary','link'));}
async function copyShare(id){const url=location.href.split('#')[0]+'#share/'+id;try{await navigator.clipboard.writeText(url);toast('已复制仅含虚构数据的进度演示链接')}catch{openDrawer('演示分享链接',`${field('复制此链接','shareURL',url)}<div class="note">仅用于高保真演示，不含真实客户数据。</div>`)} }
function renderShare(){const o=orders.find(o=>o.id===route[1])||orders[0],p=products[o.p];document.title='订单进度 · 梧桐朴鲤';document.getElementById('app').innerHTML=`<main class="sharepage"><a href="#production/progress" class="textbtn">${ic('back')}返回内部演示</a><div class="brand"><span class="brandmark">${ic('leaf')}</span><span><strong>梧桐朴鲤</strong><small>WUTONG PULI</small></span></div><div class="hero"><div class="eyebrow" style="color:#b0c2a7">YOUR ORDER JOURNEY</div><h1>${o.sent===o.qty?'本单商品，已全部发出。':'好衣，正在向你而来。'}</h1><p>${o.id} · 订单进度</p></div><section class="panel pad">${productcell(p)}<dl class="detailgrid"><div><dt>订货数量</dt><dd>${o.qty} 件</dd></div><div><dt>约定交期</dt><dd>2026-${o.date}</dd></div></dl><div class="timeline">${orderTimeline(o)}</div></section><p class="tiny" style="text-align:center;margin-top:22px">更新时间 2026.11.14 10:26 · 虚构订单进度演示<br>正式分享需服务端授权、有效期与撤销能力</p></main>`}
function collabForm(){openDrawer('新建协同报单',`<div class="formgrid">${selectfield('款式','reportProduct',products.map(p=>p.id+' '+p.name))}${field('需求数量','reportQty',100,'number')}${field('需求交期','reportDate','2026-11-25','date')}${selectfield('客户需求','reportCustomer',customers.map(c=>c.name))}</div><div class="note">此处仅收集销售生产需求，打样、BOM 和工艺开发由 PC 后台管理。</div>`,btn('提交报单','saveReport()','primary'));}
function saveReport(){const q=+document.getElementById('reportQty').value;if(q<1||!Number.isInteger(q)){toast('请填写正整数需求量');return}state.manualReports=state.manualReports||[];state.manualReports.unshift(['BD261114M'+(state.manualReports.length+1),'手工协同报单',products[+document.getElementById('reportProduct').value].id,q,pill('待确认','amber')]);closeDrawer();nav('production/reports');render();toast('协同需求已提交，等待确认')}
function smartPage(){return `<div class="toolbar"><div class="note">建议先解释依据，确认后再生成报单。支持修改、驳回或作废。</div>${btn('自定义报单规则','smartRules()','','settings')}</div><div class="three">${state.suggestions.map((s,i)=>`<section class="panel pad"><div class="actions" style="justify-content:space-between"><span class="tiny">建议 BD-S00${i+1}</span>${pill(s.status,s.status==='待确认'?'amber':s.status==='已驳回'?'gray':'')}</div><div style="margin-top:22px">${productcell(products[s.p])}</div><div class="kpi-value" style="margin:24px 0">${s.qty}<small>件建议报单</small></div><p class="tiny">${s.reason}</p><div class="rowline"><span>规则版本</span><b>补货规则 V2</b></div><div class="rowline"><span>预计交付</span><b>11 月 25 日</b></div><div class="actions" style="margin-top:20px">${s.status==='待确认'?btn('查看并确认',`suggestionDetail(${i})`,'primary')+btn('驳回',`rejectSuggestion(${i})`,'textbtn'):btn('查看依据',`suggestionDetail(${i})`,'soft')}</div></section>`).join('')}</div>`}
function suggestionDetail(i){let s=state.suggestions[i];openDrawer('智能报单建议',`${productcell(products[s.p])}<div style="margin-top:24px">${table(['计算依据','数量'],[['未分配需求（含销量预测）',s.p===0?'80':'110'],['目标自由库存','20'],['自由可用库存','−15'],['交期内未分配确认供给','−30'],['其他有效待确认建议','−10'],['原始缺口',s.p===0?'45':'75'],['整包取整后建议量',s.p===0?'50':'80']])}</div><p class="tiny" style="margin:12px 0 22px">上述为公式解释示例。调整数量需填写原因，正式确认前重新校验实时需求。</p>${field('本次确认数量','smartQty',s.qty,'number')}${field('调整说明','smartReason','按当前销售计划确认')}<div class="note">确认后才创建正式协同报单，不会在建议阶段自动下达生产。</div>`,s.status==='待确认'?btn('驳回建议',`rejectSuggestion(${i})`,'danger')+btn('确认生成报单',`approveSuggestion(${i})`,'primary','check'):btn('关闭','closeDrawer()','primary'));}
function approveSuggestion(i){const q=+document.getElementById('smartQty').value;if(!Number.isInteger(q)||q<1){toast('请填写正整数报单数量');return}if(state.suggestions[i].status!=='待确认')return;state.suggestions[i].qty=q;state.suggestions[i].status='已确认';closeDrawer();render();toast('已人工确认，协同报单列表已新增记录')}
function rejectSuggestion(i){openDrawer('驳回智能建议',`${field('驳回原因','rejectReason','当前销售计划调整，暂不补货')}<div class="note">驳回后保留建议依据与操作记录，冷却期内不重复推送。</div>`,btn('确认驳回',`if(!document.getElementById('rejectReason').value.trim()){toast('请填写原因')}else{state.suggestions[${i}].status='已驳回';closeDrawer();render();toast('建议已驳回')}`,'primary'));}
function smartRules(){openDrawer('自定义智能报单规则',`<div class="formgrid">${selectfield('报单策略','smartStrategy',['欠货与销量组合','仅客户欠货','销量覆盖天数'])}${field('安全库存 / 件','smartSafe',20,'number')}${field('覆盖天数','smartDays',14,'number')}${field('整包倍数','smartPack',10,'number')}${field('最大建议量 / 件','smartMax',500,'number')}${field('建议有效期 / 小时','smartValid',24,'number')}</div><label class="checkrow"><input type="checkbox" checked disabled>每一条建议必须由负责人确认</label><div class="note">已分配库存与供给不重复抵减；晚于交期的在产不计为按期可用供给。</div>`,btn('保存规则',"saveConfig('智能报单规则已保存');closeDrawer()",'primary'));}

function trendChart(){const values=state.period==='week'?[120,165,135,190,170,220,205]:[90,145,120,185,165,235,210],points=values.map((v,i)=>`${48+i*75},${265-v}`).join(' ');return `<svg class="chart" viewBox="0 0 540 235" role="img" aria-label="销售额趋势折线图"><defs><linearGradient id="chartFill" x2="0" y2="1"><stop stop-color="#a9bd94" stop-opacity=".35"/><stop offset="1" stop-color="#a9bd94" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map((y,i)=>`<path class="grid" d="M45 ${y}H520"/><text x="0" y="${y+4}">${[30,20,10,0][i]}k</text>`).join('')}<path d="M48 190 ${points.split(' ').map(x=>'L'+x).join(' ')} L498 190Z" fill="url(#chartFill)"/><polyline points="48,170 123,150 198,163 273,120 348,138 423,100 498,113" fill="none" stroke="#bcc9b2" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${points}" fill="none" stroke="#507453" stroke-width="2.6"/>${values.map((v,i)=>`<circle cx="${48+i*75}" cy="${265-v}" r="4" fill="#fff" stroke="#507453" stroke-width="2"/><text x="${35+i*75}" y="222">${state.period==='week'?'11.'+(8+i):'11.'+(2+i*2)}</text>`).join('')}</svg>`}
function analyticsPage(){const sub=route[1]||'overview';return head('SALES INTELLIGENCE','数据分析','从销售里看见趋势，从合作里发现长期价值。',`<div class="segmented">${btn('本周',"state.period='week';render()",state.period==='week'?'active':'')}${btn('本月',"state.period='month';render()",state.period==='month'?'active':'')}</div>`+btn('导出分析','exportCurrent()','','download'))+kpis([['净销售额',state.period==='month'?'¥186,420':'¥68,240','','<b>+18.6%</b> 较上一周期','money'],['净销售件数',state.period==='month'?'1,286':'486','件','<b>+12.8%</b> 有效实发 − 生效退货','product'],['复购客户占比','62.5','%','<b>+6.2%</b> 按购买事件计算','customers'],['期间退货比例','3.2','%','按本期退货 / 本期实发','returns']])+tabs([['销售总览','analytics/overview'],['客户深度分析','analytics/customers'],['款式深度分析','analytics/products'],['经营标签','analytics/tags']])+(sub==='tags'?tagsPage():sub==='customers'?panel('客户价值分析',table(['客户','经营标签','净成交','复购订单','账期表现',''],customers.map((c,i)=>[c.name,pill(c.tags),money(c.total),c.orders+' 单',c.days?pill('逾期 '+c.days+' 天','amber'):pill('付款及时'),btn('深度档案',`customerDetail(${i})`,'textbtn','arrow')]))):sub==='products'?panel('款式表现分析',table(['款式','近 14 天净销量','可售库存','经营判断',''],products.map(p=>[productcell(p),p.sales,p.stock,pill(p.warn?'低动销待观察':'持续动销',p.warn?'amber':''),btn('深度档案',`productDetail('${p.id}','sales')`,'textbtn','arrow')]))):`<div class="two"><section class="panel pad"><div class="actions" style="justify-content:space-between"><h2>销售额趋势</h2><span class="tiny">2026 年 11 月 · 人民币</span></div><div style="margin-top:20px">${trendChart()}</div><div class="chartlegend"><span><i></i>本期净销售额</span><span><i class="light"></i>上一可比周期</span></div></section><section class="panel pad"><div class="actions" style="justify-content:space-between"><h2>优质款式排行</h2><a class="tiny" href="#analytics/products">查看全部</a></div>${products.slice(0,4).map((p,i)=>`<div class="rank"><em>0${i+1}</em><div class="rankbody"><h3><a href="javascript:void(0)" onclick="productDetail('${p.id}','sales')">${esc(p.name)}</a><b>${p.sales} 件</b></h3><div class="progress"><i style="width:${p.sales/128*100}%"></i></div><p>${p.id}</p></div></div>`).join('')}</section></div><div style="margin-top:22px">${panel('值得持续经营的客户',table(['客户','类型','净成交','经营标签','建议动作'],customers.slice(0,3).map((c,i)=>[c.name,c.type,money(c.total),pill(c.tags),btn('查看客户档案',`customerDetail(${i})`,'textbtn','arrow')])))}</div>`);}
function tagsPage(){return `<div class="three">${state.tags.map(([t,d,o],i)=>`<section class="panel pad"><div class="eyebrow">${o==='客户'?'CUSTOMER TAG':'PRODUCT TAG'}</div><h2>${esc(t)}</h2><p class="subtle" style="font-size:12px;margin:18px 0">${d}</p>${pill('规则标签 · 可解释','blue')}${btn('编辑标签',`tagForm(${i})`,'textbtn','edit')}</section>`).join('')}</div><div class="note" style="margin-top:22px">经营结论按月归档。评分、标签阈值和样本量均可配置，旧快照不被新规则覆盖。</div>`}
function tagForm(i){state.editingTag=i;const t=state.tags[i][0];openDrawer('编辑经营标签',`${field('标签名称','tagName',t)}${field('观察窗口 / 天','tagDays',90,'number')}${field('最低样本量','tagMin',3,'number')}<div class="field"><label>经营结论</label><textarea>保持定期回访，结合客户偏好推荐适配款式。</textarea></div>`,btn('保存标签',"saveTag()",'primary'));}

function saveTag(){const name=document.getElementById('tagName').value.trim();if(!name){toast('请填写标签名称');return}state.tags[state.editingTag][0]=name;closeDrawer();render();toast('标签已更新')}
function staffPage(){const sub=route[1]||'members';return head('FULFILLMENT TEAM','配货职工管理','记录每一份认真，让配货表现与提成清晰可核对。',btn('导出提成','exportCurrent()','','download')+btn('新增成员','memberForm()','primary','plus'))+tabs([['成员档案','staff/members',members.length],['配货数据','staff/performance'],['提成核算','staff/commission'],['管理条约','staff/terms']])+(sub==='terms'?termsPage():sub==='commission'?commissionPage():sub==='performance'?panel('本月配货统计',table(['成员','有效配货','配货单数','复核准确率','预估提成',''],members.map((m,i)=>[m.name,m.qty+' 件',m.bills+' 单',m.rate+'%',money(m.pay),btn('配货明细',`memberDetail(${i})`,'textbtn','arrow')]))):`<div class="three">${members.map((m,i)=>`<section class="panel member"><div class="memberhead">${avatar(i)}<div><h3>${esc(m.name)}</h3><p class="tiny">${esc(m.role)} · 杭州总仓</p></div></div>${pill('在职')}${pill('条约 V'+state.termsVersion+(state.termsVersion===3?' 已确认':' 待确认'),'gray')}<div class="memberstats"><div><b>${num(m.qty)}</b><small>本月有效配货 / 件</small></div><div><b>${m.rate}%</b><small>复核准确率</small></div></div><div class="rowline" style="margin-top:12px"><span class="tiny">预估提成</span><b>${money(m.pay)}</b></div><div style="margin-top:16px">${btn('成员详情',`memberDetail(${i})`,'soft','arrow')}</div></section>`).join('')}</div><div class="note" style="margin-top:22px">成员照片、配货记录、复核证据与条约确认统一留档。绩效指标用于复盘改进，提成需独立复核后发放。</div>`);}
function memberDetail(i){const m=members[i];openDrawer('成员档案 · '+m.name,`<div class="memberhead">${avatar(i)}<div><h2>${esc(m.name)}</h2><p class="tiny">${esc(m.role)} · WT-00${26+i}</p></div></div><dl class="detailgrid"><div><dt>有效配货</dt><dd>${m.qty} 件</dd></div><div><dt>预估提成</dt><dd>${money(m.pay)}</dd></div><div><dt>入职日期</dt><dd>2025.09.01</dd></div><div><dt>条约签收</dt><dd>V${state.termsVersion} · ${state.termsVersion===3?'已确认':'待确认'}</dd></div></dl>${table(['配货单','归属数量','提成基数'],[['PH26111401','60 件','¥30.00'],['PH26111402','40 件','¥20.00'],['PH26111306','80 件','¥40.00']])}<div class="note" style="margin-top:20px">多人配货按任务行分摊，归属总量不得超过有效配货量。上表为近期明细节选。</div>`,btn('查看提成核算',"closeDrawer();nav('staff/commission')",'primary'));}
function memberForm(){openDrawer('新增配货成员',`${field('姓名','memberName')}${selectfield('岗位','memberRole',['配货专员','配货组长','复核专员'])}${field('入职日期','memberDate','2026-11-14','date')}`,btn('保存成员',"saveMember()",'primary'));}
function saveMember(){const name=document.getElementById('memberName').value.trim();if(!name){toast('请输入成员姓名');return}members.push({name,role:['配货专员','配货组长','复核专员'][+document.getElementById('memberRole').value],qty:0,bills:0,rate:100,pay:0});closeDrawer();render();toast('成员已添加')}
function commissionPage(){return kpis([['本期有效配货',num(members.reduce((a,m)=>a+m.qty,0)),'件','2026.11.01 - 11.14'],['基础提成',money(members.reduce((a,m)=>a+m.pay,0)),'','每件 ¥0.50 · 方案 V2'],['跨期调整','−¥5.00','','上期退货关联调整'],['结算状态',state.locked?'已锁定':'待复核','','锁定后通过调整单更正']])+panel('提成发放核对表',table(['成员','有效件数','基础提成','跨期调整','本期应发','状态'],members.map((m,i)=>[m.name,m.qty,money(m.pay),i===0?'−¥5.00':'¥0.00',money(m.pay-(i===0?5:0)),pill(state.locked?'已锁定':'待复核',state.locked?'':'amber')])),btn(state.locked?'查看结算说明':'复核与锁定',state.locked?"toast('当前期间已锁定；后续更正应通过调整单进入下期')":"lockCommission()",'soft','shield'))+`<div class="note" style="margin-top:22px">退货扣回须有原提成明细与责任复核；已锁账月份不改写，跨期调整在下期体现。当前为核算演示，不会实际发放工资。</div>`}
function lockCommission(){openDrawer('复核本期提成',`<h2>2026 年 11 月配货提成</h2><div class="rowline"><span>本期应发合计</span><b>${money(members.reduce((a,m)=>a+m.pay,0)-5)}</b></div><label class="checkrow"><input id="lockCheck" type="checkbox">已核对有效配货、多人分摊和跨期退货调整</label><div class="note amber">锁定后保留本期金额。后续更正通过关联调整行处理。</div>`,btn('确认复核并锁定',"if(!document.getElementById('lockCheck').checked){toast('请先确认核对内容')}else{state.locked=true;closeDrawer();render();toast('本期提成已锁定 · 演示')}",'primary'));}
function termsPage(){return `<section class="panel"><div class="panelhead"><div><h2>配货岗位管理条约</h2><p class="tiny" style="margin-top:8px">V${state.termsVersion} · 生效日期 2026.11.01 · 适用杭州总仓</p></div><div class="actions">${btn('导出打印','window.print()','','printer')}${btn('编辑新版本','termsForm()','soft','edit')}</div></div><div style="counter-reset:rule">${state.terms.map(t=>`<div class="rule"><div><h3>岗位操作与协作要求</h3><p>${esc(t)}</p></div></div>`).join('')}</div><div class="pad"><div class="note">新版本发布后重新确认，旧版签收记录保留。条约文本变更不会自动改变工资核算方案。</div><p class="printonly" style="margin-top:35px">员工签名：________________　确认日期：________________</p></div></section>`}
function termsForm(){openDrawer('编辑管理条约新版本',`<div class="field"><label for="termsText">每行一条，可添加第 4 条及更多条款</label><textarea id="termsText" style="min-height:240px">${esc(state.terms.join('\n'))}</textarea></div><div class="note">保存后生成 V${state.termsVersion+1}，成员确认状态将变为待确认。</div>`,btn('发布新版本','saveTerms()','primary'));}
function saveTerms(){const terms=document.getElementById('termsText').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!terms.length){toast('请至少填写一条条约');return}state.terms=terms;state.termsVersion++;closeDrawer();render();toast('新条约已发布，等待成员确认 · 演示')}

function scanPage(){return head('TRACEABILITY','扫码查询','扫一件衣服，看清款式、颜色和它走过的每一步。')+`<div class="two"><section class="panel pad"><div class="scanbox"><div class="scanframe">${garment(products[0])}</div><small>摄像头扫描区域 · 设计示意</small></div><div class="field" style="margin-top:22px"><label for="scanCode">输入商品码或来源批次码</label><input id="scanCode" placeholder="例如 WT-2608 或 B26111208" onkeydown="if(event.key==='Enter')scanQuery()"></div><div class="actions">${btn('查询来源','scanQuery()','primary','scan')}${btn('模拟扫描批次',"document.getElementById('scanCode').value='B26111208';scanQuery()",'soft')}</div><p class="error" id="scanError"></p></section><section class="panel pad" id="scanResult"><div class="empty">${ic('scan')}<h2 style="margin:20px 0 10px">等待识别衣服来源</h2><p class="tiny">商品码识别款色码<br>批次码进一步定位入库与加工来源</p></div></section></div>`}
function scanQuery(){const v=document.getElementById('scanCode').value.trim().toUpperCase(),p=products.find(p=>p.id===v),batch=v==='B26111208';if(!p&&!batch){document.getElementById('scanError').textContent='未找到该码。可使用 WT-2608 或 B26111208 体验。';return}document.getElementById('scanError').textContent='';const item=p||products[0];document.getElementById('scanResult').innerHTML=`${pill('识别成功')}<div style="margin-top:22px">${productcell(item)}</div><dl class="detailgrid"><div><dt>颜色 / 尺码</dt><dd>${item.colorName} / M</dd></div><div><dt>成分</dt><dd>${item.composition}</dd></div><div><dt>可售库存</dt><dd>${item.stock} 件</dd></div><div><dt>来源粒度</dt><dd>${batch?'已定位生产批次':'商品码 / 待选择批次'}</dd></div></dl>${batch?`<h3>衣服来源链路</h3><div class="timeline"><div class="event active"><b>成品入库 RK26111208</b><p>杭州总仓 / A-02 · 2026.11.12</p></div><div class="event"><b>质检通过</b><p>对应批次 B26111208</p></div><div class="event"><b>生产单 SC26111001</b><p>经授权展示的生产来源摘要</p></div></div>`:'<div class="note">此商品存在多个批次。请扫描来源批次码，以免把同款商品误认为同一来源。</div>'}`}

function settingsPage(){const sub=route[1]||'business';return head('WORKSPACE SETTINGS','系统设置','让业务规则清楚、权限合适，每一次更改都有记录。')+tabs([['业务参数','settings/business'],['组织与权限','settings/permissions'],['通知中心','settings/notifications'],['数据与打印','settings/data']])+(sub==='permissions'?panel('角色权限范围',table(['角色','客户订单','库存与配货','账款与提成','规则审批'],[['负责人','全部授权门店','查询 / 审核','查询 / 复核','确认 / 驳回'],['销售员','本人负责客户','查看可售库存','授权客户账款','无'],['仓库配货','关联配货任务','收发 / 盘点','仅本人提成','无'],['财务主管','结算相关订单','只读','核销 / 结算 / 锁定','财务审批']]))+`<div class="note" style="margin-top:22px">此页面为权限设计示意。公开原型使用虚构数据，不具备正式身份认证与权限隔离。</div>`:sub==='notifications'?`<section class="panel pad">${[['启用站内待办','订单交期、下架建议和待审批事项','notifications'],['启用催款提醒','仅内部提醒，不向客户实际发送','reminder']].map(([t,d,k])=>`<div class="rowline"><div><h3>${t}</h3><p class="tiny">${d}</p></div><button class="toggle ${state[k]?'on':''}" aria-label="${t}" onclick="state.${k}=!state.${k};render()"></button></div>`).join('')}<div class="formgrid" style="margin-top:22px">${field('安静时段开始','quietStart','21:00','time')}${field('安静时段结束','quietEnd','08:00','time')}</div>${btn('保存通知设置',"saveConfig('通知设置已保存')",'primary')}</section>`:sub==='data'?`<div class="two"><section class="panel pad"><h2>数据导出</h2><p class="subtle" style="margin:18px 0;font-size:12px">下载当前演示数据，便于检查字段与核对报表。</p>${btn('导出货品与库存','exportCurrent()','primary','download')}<div class="note" style="margin-top:20px">CSV 可用 Excel 打开，正式系统的导出应继承数据权限。</div></section><section class="panel pad"><h2>打印设置</h2><div style="margin-top:20px">${selectfield('纸张规格','paper',['A4 标准单据','80 mm 小票','100 × 60 mm 标签'])}${btn('打开打印预览','window.print()','soft','printer')}</div></section></div>`:`<div class="two"><section class="panel pad"><h2 style="margin-bottom:24px">销售与库存参数</h2><div class="formgrid">${selectfield('应收生效时点','arPoint',['出库过账时','财务确认时'])}${selectfield('盘点模式','countMode',['冻结盘点范围','动态截止点对账'])}${selectfield('普通退货恢复欠货','returnDebt',['不自动恢复','创建补发需求后恢复'])}${field('默认客户账期 / 天','creditDays',30,'number')}</div>${btn('保存业务参数',"saveConfig('业务参数已保存 · 演示')",'primary')}</section><section class="panel pad"><h2>规则快捷入口</h2>${[['下架通知规则','产品销量与保护条件','delistRules()'],['智能报单规则','需求、库存与整包倍数','smartRules()'],['客户催款','账期与提醒频率',"nav('customers/reminders')"],['配货提成','核算、复核与锁定',"nav('staff/commission')"]].map(([t,d,a])=>`<div class="rowline"><div><b>${t}</b><p class="tiny">${d}</p></div>${btn('',a,'iconbtn','arrow')}</div>`).join('')}</section></div>`);}
function saveConfig(message){const inputs=[...document.querySelectorAll('.main input,.drawer input')].filter(e=>e.type==='number');if(inputs.some(e=>e.value===''||Number(e.value)<0)){toast('请检查数值，不能留空或小于零');return}for(const e of document.querySelectorAll('.main input[id],.main select[id],.drawer input[id],.drawer select[id]'))state.config[e.id]=e.value;toast(message)}
function notifications(){openDrawer('今日待办',`<div class="rowline"><div><b>下架建议待处理</b><p class="tiny">${products.filter(p=>p.warn&&!p.off&&!p.ignored).length} 款低动销商品需要决定</p></div>${btn('',"closeDrawer();nav('products/delist')",'iconbtn','arrow')}</div><div class="rowline"><div><b>智能报单待确认</b><p class="tiny">${state.suggestions.filter(s=>s.status==='待确认').length} 条建议等待你的确认</p></div>${btn('',"closeDrawer();nav('production/smart')",'iconbtn','arrow')}</div><div class="rowline"><div><b>客户账款需跟进</b><p class="tiny">杭州青禾与上海素集有逾期款项</p></div>${btn('',"closeDrawer();nav('customers/accounts')",'iconbtn','arrow')}</div>`,btn('关闭','closeDrawer()','primary'));}
function globalSearch(){openDrawer('搜索工作台',`${field('款号、客户名称或订单号','globalQ','','text','输入后点击搜索')}<div id="globalResults"></div>`,btn('搜索','runSearch()','primary','search'));document.getElementById('globalQ').addEventListener('keydown',e=>{if(e.key==='Enter')runSearch()})}
function runSearch(){let q=document.getElementById('globalQ').value.trim().toLowerCase();if(!q){toast('请输入关键词');return}let list=[];products.forEach(p=>{if((p.id+p.name).toLowerCase().includes(q))list.push(`<div class="rowline"><div>${p.id}<p class="tiny">${esc(p.name)}</p></div>${btn('查看',`productDetail('${p.id}')`,'soft')}</div>`)});customers.forEach((c,i)=>{if(c.name.toLowerCase().includes(q))list.push(`<div class="rowline"><span>${esc(c.name)}</span>${btn('查看',`customerDetail(${i})`,'soft')}</div>`)});orders.forEach(o=>{if(o.id.toLowerCase().includes(q))list.push(`<div class="rowline"><span>${o.id}</span>${btn('查看',`closeDrawer();nav('orders/${o.id}')`,'soft')}</div>`)});document.getElementById('globalResults').innerHTML=list.join('')||'<div class="empty">暂无匹配结果</div>'}
render();
